import{_ as t,o as n,c as s,ah as a}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Démarches","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/parent/demarches.md","filePath":"src/guide/parent/demarches.md"}'),r={name:"guide/parent/demarches.md"};function o(i,e,u,l,d,c){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="demarches" tabindex="-1">Démarches <a class="header-anchor" href="#demarches" aria-label="Permalink to &quot;Démarches&quot;">​</a></h1><p>Cette page explique deux démarches que vous pouvez effectuer vous-même pour un enfant, sans passer par le secrétariat : justifier une absence et demander un transfert de site.</p><h2 id="justifier-une-absence" tabindex="-1">Justifier une absence <a class="header-anchor" href="#justifier-une-absence" aria-label="Permalink to &quot;Justifier une absence&quot;">​</a></h2><p>Quand votre enfant a été marqué absent ou en retard, vous pouvez envoyer une justification directement depuis sa fiche :</p><ol><li>Sur la fiche de l&#39;enfant, allez dans la section <strong>Présences</strong>.</li><li>Repérez la ligne correspondant au jour concerné (statut <strong>Absent</strong> ou <strong>Retard</strong>) et cliquez sur <strong>Justifier</strong>.</li><li>Dans la fenêtre <strong>Justifier cette absence</strong>, saisissez le <strong>Motif</strong>.</li><li>Si vous avez un document à l&#39;appui (certificat médical, etc.), ajoutez-le dans <strong>Pièce justificative</strong> — formats acceptés : PDF, JPG ou PNG. Ce champ est optionnel.</li><li>Cliquez sur <strong>Envoyer</strong>.</li></ol><p>Votre justification apparaît alors avec le statut <strong>En attente d&#39;examen</strong>. L&#39;établissement l&#39;examine et la fait passer à <strong>Justifiée</strong> ou <strong>Rejetée</strong> ; le statut se met à jour directement sur la fiche de votre enfant.</p><h2 id="demander-un-transfert-de-site" tabindex="-1">Demander un transfert de site <a class="header-anchor" href="#demander-un-transfert-de-site" aria-label="Permalink to &quot;Demander un transfert de site&quot;">​</a></h2><p>Si vous souhaitez inscrire votre enfant sur un autre site de l&#39;établissement (un autre campus, par exemple), vous pouvez soumettre une demande de transfert :</p><ol><li>Sur la fiche de l&#39;enfant, allez dans la section <strong>Mobilité inter-site</strong>.</li><li>Cliquez sur <strong>Demander un transfert</strong> — ce bouton n&#39;est disponible que si aucune demande n&#39;est déjà en attente pour cet enfant.</li><li>Dans la fenêtre <strong>Demander un transfert inter-site</strong>, choisissez le <strong>Site de destination</strong> et le <strong>Département de destination</strong> souhaités.</li><li>Ajoutez un <strong>Motif</strong> si vous le souhaitez (facultatif).</li><li>Cliquez sur <strong>Envoyer la demande</strong>.</li></ol><p>La demande apparaît dans le tableau en dessous avec la date, le site d&#39;origine, le site de destination et son statut : <strong>En attente</strong>, <strong>Approuvé</strong> ou <strong>Refusé</strong>. Tant qu&#39;une demande est en attente, vous ne pouvez pas en soumettre une nouvelle pour le même enfant.</p>',10)])])}const f=t(r,[["render",o]]);export{m as __pageData,f as default};
